const GetGuildTimeToFirstMessage = `-- name: GetGuildTimeToFirstMessage :one
WITH joined AS (
    SELECT DISTINCT ON (user_id)
        user_id,
        created_at AS joined_at
    FROM science_guild_events
    WHERE science_guild_events.guild_id = $1
        AND science_guild_events.event_type = $2
        AND science_guild_events.user_id IS NOT NULL
        AND science_guild_events.created_at BETWEEN $3 AND $4
    ORDER BY science_guild_events.user_id, science_guild_events.created_at
),
first_messages AS (
    SELECT guild_message_counts_hour.user_id, MIN(guild_message_counts_hour.min_ts) AS first_at
    FROM guild_message_counts_hour
    WHERE guild_message_counts_hour.guild_id = $1
        AND guild_message_counts_hour.hour_ts BETWEEN $3 AND $4
    GROUP BY guild_message_counts_hour.user_id
),
durations AS (
    SELECT EXTRACT(EPOCH FROM first_messages.first_at - joined.joined_at)::bigint AS seconds
    FROM joined
    INNER JOIN first_messages USING (user_id)
    WHERE first_messages.first_at >= joined.joined_at
)
SELECT
    COUNT(*)::bigint AS users,
    COALESCE(AVG(seconds), 0)::bigint AS average_seconds,
    COALESCE(percentile_cont(0.5) WITHIN GROUP (ORDER BY seconds), 0)::bigint AS median_seconds
FROM durations
`

type GetGuildTimeToFirstMessageParams struct {
	GuildID       int64     `json:"guild_id"`
	JoinEventType int32     `json:"join_event_type"`
	DateFrom      time.Time `json:"date_from"`
	DateTo        time.Time `json:"date_to"`
}

type GetGuildTimeToFirstMessageRow struct {
	Users          int64 `json:"users"`
	AverageSeconds int64 `json:"average_seconds"`
	MedianSeconds  int64 `json:"median_seconds"`
}

func (q *Queries) GetGuildTimeToFirstMessage(ctx context.Context, arg GetGuildTimeToFirstMessageParams) (*GetGuildTimeToFirstMessageRow, error) {
	row := q.db.QueryRow(ctx, GetGuildTimeToFirstMessage,
		arg.GuildID,
		arg.JoinEventType,
		arg.DateFrom,
		arg.DateTo,
	)
	var i GetGuildTimeToFirstMessageRow
	err := row.Scan(&i.Users, &i.AverageSeconds, &i.MedianSeconds)
	return &i, err
}

